INSERT INTO "pages" ("slug", "title", "blocks", "status", "updated_at") VALUES
('blog-porto-in-one-day-without-racing', 'Porto in one day — without racing through it', $json$[
  {"id":20001,"type":"Hero","eyebrow":"Porto itineraries","title":"Porto in one day — without racing through it","description":"A walkable route through tiled stations, iron architecture, steep streets and the Douro — with enough time left to actually look around.","background":"#11110f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":20002,"type":"Texto","eyebrow":"Morning · Baixa","title":"Start where the city explains itself","description":"Begin at São Bento station and take a proper look at the tiled entrance hall. Continue to Mercado do Bolhão for the everyday rhythm of the city, then walk down through Rua das Flores. Porto rewards slow walking: granite façades, narrow shopfronts and sudden views appear between the famous stops.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20003,"type":"Texto","eyebrow":"Lunch · Historic centre","title":"Follow the slope towards the river","description":"Pass Largo de São Domingos and Palácio da Bolsa before arriving at Mercado Ferreira Borges. The red iron building dates from 1885 and now houses Hard Club and River Market. This is also where you can find Made in Maia in Porto — a good stop for an independent souvenir that does not look like every other souvenir.","ctaLabel":"Find us at Mercado Ferreira Borges","ctaUrl":"https://rivermarket.pt","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":20004,"type":"Texto","eyebrow":"Afternoon · Ribeira","title":"Cross the postcard, then leave room for real life","description":"Walk through Praça da Ribeira and along the Douro. Cross Luís I Bridge if your legs agree, or stay on the Porto side and explore the lanes behind the riverfront. The historic centre has been UNESCO World Heritage since 1996, but it is still a lived-in neighbourhood — be considerate in residential streets.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20005,"type":"Texto","eyebrow":"Golden hour","title":"Finish above the river","description":"Climb towards Passeio das Virtudes for a relaxed sunset, or choose the gardens of Palácio de Cristal for more space and several viewpoints over the Douro. Porto is steep: comfortable shoes will improve the day more than another item on the checklist.","ctaLabel":"Official historic centre guide","ctaUrl":"https://visitporto.travel/en-GB/districts/historic","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),
('blog-porto-markets-iron-and-local-life', 'Porto markets: iron, food and local life', $json$[
  {"id":20101,"type":"Hero","eyebrow":"Markets & local life","title":"Porto markets: iron, food and local life","description":"Two very different market buildings tell a useful story about Porto: one still feeds the city; the other became a cultural stage.","background":"#8d2b20","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":20102,"type":"Texto","eyebrow":"Mercado do Bolhão","title":"The market that stayed a market","description":"Bolhão sits in the centre of the city and remains a working fresh-food market, surrounded by small restaurants and shops. Go early enough to see the stalls in full rhythm. Buy what you will actually eat, ask before photographing people, and remember that this is a workplace before it is an attraction.","ctaLabel":"Official Bolhão information","ctaUrl":"https://www.cm-porto.pt/mercados/mercado-do-bolhao","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20103,"type":"Texto","eyebrow":"Mercado Ferreira Borges","title":"The market that found a second life","description":"Built in 1885 to replace the old Ribeira market, Ferreira Borges had a short original career as a market. Its iron structure survived and the building was adapted for culture and events. Today it houses Hard Club and River Market — including the Made in Maia spot.","ctaLabel":"See the official listing","ctaUrl":"https://visitporto.travel/en-GB/poi/5cd04b4ef979e00001fe4824","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":20104,"type":"Texto","eyebrow":"Buy better","title":"A souvenir can support the place you visited","description":"Look for work made or designed locally, ask where it comes from and choose objects you will keep using. Independent prints, ceramics, food products and books carry more of Porto home than a generic object with the city name added later.","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),
('blog-porto-viewpoints-for-every-kind-of-day', 'Porto viewpoints for every kind of day', $json$[
  {"id":20201,"type":"Hero","eyebrow":"Views & walks","title":"Porto viewpoints for every kind of day","description":"Big horizons, quiet gardens and sunset terraces — pick a view that matches your energy instead of collecting them all.","background":"#243b6b","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":20202,"type":"Texto","eyebrow":"For the first panorama","title":"Terreiro da Sé","description":"The cathedral terrace gives an immediate reading of the old city: roofs, tight streets and the river below. It is central and easy to combine with a walk towards São Bento or Ribeira, although the surrounding slopes are real.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20203,"type":"Texto","eyebrow":"For sunset energy","title":"Passeio das Virtudes","description":"Virtudes faces the Douro from a set of terraces and has become a popular late-afternoon meeting point. Arrive before sunset, bring only what you need and leave the garden as you found it. If it feels too busy, continue walking rather than forcing the moment.","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":20204,"type":"Texto","eyebrow":"For space and gardens","title":"Palácio de Cristal","description":"The gardens offer several smaller viewpoints rather than one single photo stop. From different terraces you can see the Douro, Serra do Pilar, the Gaia riverfront and Arrábida Bridge. It is the better choice when you want a longer, slower break.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20205,"type":"Texto","eyebrow":"The useful list","title":"Choose by route, not by ranking","description":"Porto's official viewpoint guide includes natural high points and built landmarks across the city. Use it to find one close to the route you already planned. The best view is often the one that gives your day room to breathe.","ctaLabel":"Explore Porto's official viewpoints","ctaUrl":"https://visitporto.travel/en-GB/poi/66057cab43ba490001440c66","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),
('blog-getting-around-porto-without-losing-the-day', 'Getting around Porto without losing the day', $json$[
  {"id":20301,"type":"Hero","eyebrow":"Practical Porto","title":"Getting around Porto without losing the day","description":"A simple transport strategy for hills, airport arrivals and days when walking stops being charming.","background":"#174f3b","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":20302,"type":"Texto","eyebrow":"The basic idea","title":"Walk the centre; use transport to change districts","description":"Baixa and the historic centre are compact enough to explore on foot, but Porto is steep. Metro and buses are most useful for the airport, longer cross-city moves and the return journey after a downhill walk. Plan around neighbourhoods instead of travelling back and forth between isolated landmarks.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20303,"type":"Texto","eyebrow":"Andante","title":"Zones count outwards from where the trip starts","description":"Occasional Andante journeys use a zone system. A Z2 covers two zone rings from the first validation point; Z3 covers three, and so on. The required product depends on the route, so check the official journey or zone information instead of guessing from distance alone.","ctaLabel":"Check official Andante zones","ctaUrl":"https://andante.pt/comprar/andante-azul/zonas/","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":20304,"type":"Texto","eyebrow":"Small habits","title":"Validate, keep the card and allow for hills","description":"Validate as required when you travel, keep the reusable card during your stay and do not schedule every connection to the minute. Lifts, funiculars and short transport hops can protect your energy, but the best discoveries still tend to happen between stops.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20305,"type":"Banner","eyebrow":"Made in Maia local note","title":"The route to us is part of the visit","description":"Mercado Ferreira Borges is a few minutes from Ribeira, Palácio da Bolsa and the Douro. Visit the building, see what is happening at River Market and say hello.","ctaLabel":"Find Made in Maia","ctaUrl":"https://rivermarket.pt","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),
('blog-why-porto-looks-like-porto', 'Why Porto looks like Porto', $json$[
  {"id":20401,"type":"Hero","eyebrow":"City stories","title":"Why Porto looks like Porto","description":"Granite, iron, tiles, slopes and adaptation: a short visual vocabulary for reading the city while you walk.","background":"#3b274f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":20402,"type":"Texto","eyebrow":"Granite","title":"A city built with weight","description":"Porto's grey granite gives churches, houses and pavements their physical presence. In wet weather it deepens in colour; in narrow streets it makes painted doors, shop signs and ceramic tiles feel brighter. The material is not a background — it sets the visual rhythm.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20403,"type":"Texto","eyebrow":"Iron","title":"Infrastructure became identity","description":"Bridges, railway structures and market halls brought industrial materials into the city's public image. Mercado Ferreira Borges is a compact example: a red iron market building from 1885 that outlived its original purpose and became a cultural venue.","ctaLabel":"Visit Mercado Ferreira Borges","ctaUrl":"https://visitporto.travel/en-GB/poi/5cd04b4ef979e00001fe4824","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":20404,"type":"Texto","eyebrow":"Azulejos","title":"Pictures that belong to architecture","description":"At São Bento, churches and residential façades, ceramic tiles work as weatherproof skin, ornament and storytelling surface. Look at how panels meet doors, stone frames and corners — the interesting part is often the way an image becomes part of a building.","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":20405,"type":"Texto","eyebrow":"Read the city","title":"Old structures keep learning new uses","description":"Porto's character comes as much from reuse as preservation. Markets become venues, warehouses become museums and old streets absorb contemporary studios. Made in Maia follows the same instinct: local references become new designs, and a label becomes a link to the next story.","ctaLabel":"Discover the Link Label","ctaUrl":"/linklabel","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now())
ON CONFLICT ("slug") DO NOTHING;
